import pytest


class Bad(Exception):
    def __init__(self, n: int) -> None:
        super().__init__(f"Bad({n})")
        self.n = n


def check(x: int) -> int:
    if x % 2 == 1:
        raise Bad(x)
    return x


def all_even(xs: list[int]) -> list[int]:
    """Check every element in parallel using a thread pool.

    Returns the checked elements in original order if all pass.
    If one or more elements fail, raises the Bad exception of the
    lowest-index bad element, regardless of thread completion order.
    """
    if not xs:
        return []

    from concurrent.futures import Future, ThreadPoolExecutor

    with ThreadPoolExecutor() as executor:
        futures: list[Future[int]] = [executor.submit(check, x) for x in xs]
        first_bad: Bad | None = None
        results: list[int] = []

        for f in futures:
            if first_bad is not None:
                f.cancel()
                continue
            try:
                results.append(f.result())
            except Bad as err:
                first_bad = err

        if first_bad is not None:
            raise first_bad

    return results


def test_all_even_empty() -> None:
    assert all_even([]) == []


def test_all_even_success() -> None:
    assert all_even([0, 2, 4, 6, 8]) == [0, 2, 4, 6, 8]


def test_all_even_single_bad() -> None:
    with pytest.raises(Bad) as exc_info:
        all_even([2, 4, 5, 8])
    assert exc_info.value.n == 5


def test_all_even_multiple_bad_raises_lowest_index() -> None:
    with pytest.raises(Bad) as exc_info:
        all_even([2, 3, 4, 5, 7, 8])
    assert exc_info.value.n == 3


def test_all_even_first_element_bad() -> None:
    with pytest.raises(Bad) as exc_info:
        all_even([1, 2, 4, 6])
    assert exc_info.value.n == 1


def test_all_even_last_element_bad() -> None:
    with pytest.raises(Bad) as exc_info:
        all_even([2, 4, 6, 7])
    assert exc_info.value.n == 7

